mapper.select:


SELECT r."id", r."username", r."nickname", r."email", r."avatar", r."bio",
       r."role", r."status", r."created_at", r."updated_at",
       (SELECT COUNT(*) FROM "BLOG"."posts" p
        WHERE p."user_id"=r."id" AND p."deleted_at" IS NULL) AS "post_count"
FROM "BLOG"."users" r

    AND r."status"=#{query.status}
    AND r."role"=#{query.role}

        AND (r."username" LIKE #{pattern}
          OR r."nickname" LIKE #{pattern}
          OR r."email" LIKE #{pattern}
          OR CAST(r."id" AS VARCHAR(30)) LIKE #{pattern})


ORDER BY r."created_at" DESC, r."id" DESC
